// Load data
var dataView = mlContext.Data.LoadFromTextFile<CustomerData>(dataPath, hasHeader: true, separatorChar: ',');

// Build training pipeline
var pipeline = mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(CustomerData.Region))
    .Append(mlContext.Transforms.Concatenate("Features", "Age", "Income", "RegionEncoded", "PurchaseHistory"))
    .Append(mlContext.Transforms.NormalizeMinMax("Features"))
    .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
        labelColumnName: "Label", featureColumnName: "Features"));

// Use cross-validation for small datasets, train/test split for larger ones
var rowCount = (int)mlContext.Data.CreateEnumerable<CustomerData>(dataView, reuseRowObject: false).Count();
ITransformer model;

if (rowCount < 20)
{
    Console.WriteLine($"Small dataset ({rowCount} rows) — using cross-validation with 3 folds.");
    var cvResults = mlContext.BinaryClassification.CrossValidate(dataView, pipeline, numberOfFolds: 3, labelColumnName: "Label");
    var avgAuc = cvResults.Average(r => r.Metrics.AreaUnderRocCurve);
    var avgAcc = cvResults.Average(r => r.Metrics.Accuracy);
    Console.WriteLine($"Cross-validation metrics — Avg AUC: {avgAuc:F4}, Avg Accuracy: {avgAcc:F4}");
    model = pipeline.Fit(dataView);
}
else
{
    var split = mlContext.Data.TrainTestSplit(dataView, testFraction: 0.2);
    model = pipeline.Fit(split.TrainSet);
    var predictions = model.Transform(split.TestSet);
    var metrics = mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: "Label");
    Console.WriteLine($"Model metrics — AUC: {metrics.AreaUnderRocCurve:F4}, Accuracy: {metrics.Accuracy:F4}, F1: {metrics.F1Score:F4}");
}

