var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "customers.csv");

// Load data with string label, then map "Yes"/"No" to boolean
var rawData = mlContext.Data.LoadFromTextFile<RawCustomerData>(dataPath, hasHeader: true, separatorChar: ',');
var dataView = mlContext.Transforms.CustomMapping<RawCustomerData, LabelMapping>(
    (input, output) => output.Label = string.Equals(input.ChurnedRaw, "Yes", StringComparison.OrdinalIgnoreCase),
    contractName: "ChurnLabelMapping")
    .Fit(rawData).Transform(rawData);

// Build training pipeline
var pipeline = mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", "Region")
    .Append(mlContext.Transforms.Concatenate("Features", "Age", "Income", "RegionEncoded", "PurchaseHistory"))
    .Append(mlContext.Transforms.NormalizeMinMax("Features"))
    .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
        labelColumnName: "Label", featureColumnName: "Features"));

// Train model and evaluate
var rowCount = (int)mlContext.Data.CreateEnumerable<RawCustomerData>(rawData, reuseRowObject: false).Count();
Console.WriteLine($"Training on {rowCount} rows...");

ITransformer model;
if (rowCount >= 20)
{
    var split = mlContext.Data.TrainTestSplit(dataView, testFraction: 0.2);
    model = pipeline.Fit(split.TrainSet);
    var predictions = model.Transform(split.TestSet);
    var metrics = mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: "Label");
    Console.WriteLine($"Model metrics — AUC: {metrics.AreaUnderRocCurve:F4}, Accuracy: {metrics.Accuracy:F4}, F1: {metrics.F1Score:F4}");
}
else
{
    // For very small datasets, train on all data (evaluation would be unreliable)
    Console.WriteLine("Dataset too small for reliable evaluation — training on all data.");
    model = pipeline.Fit(dataView);
}

// Save model
var modelPath = Path.Combine(AppContext.BaseDirectory, "churn-model.zip");
mlContext.Model.Save(model, dataView.Schema, modelPath);
Console.WriteLine($"Model saved to {modelPath}");

// Register pooled prediction engine for thread-safe web use
builder.Services.AddPredictionEnginePool<CustomerInput, ChurnPrediction>()
    .FromFile(modelPath);

var app = builder.Build();

app.MapPost("/predict", (PredictionEnginePool<CustomerInput, ChurnPrediction> pool, CustomerInput input) =>
{
    var prediction = pool.Predict(input);
    return Results.Ok(new { WillChurn = prediction.PredictedLabel, Probability = prediction.Probability });
});

app.MapGet("/", () => "Churn Predictor API — POST /predict with { age, income, region, purchaseHistory }");

app.Run();

// Input class for CSV loading (with string label)
public class RawCustomerData
{
    [LoadColumn(0)]
    public float Age { get; set; }

    [LoadColumn(1)]
    public float Income { get; set; }

    [LoadColumn(2)]
    public string Region { get; set; } = string.Empty;

    [LoadColumn(3)]
    public float PurchaseHistory { get; set; }

    [LoadColumn(4)]
    public string ChurnedRaw { get; set; } = string.Empty;
}

// Custom mapping output
public class LabelMapping
{
    public bool Label { get; set; }
}

// Input class for prediction (no label column)
public class CustomerInput
{
    public float Age { get; set; }
    public float Income { get; set; }
    public string Region { get; set; } = string.Empty;
    public float PurchaseHistory { get; set; }
}

public class ChurnPrediction
{
    [ColumnName("PredictedLabel")]
    public bool PredictedLabel { get; set; }

    public float Probability { get; set; }

    public float Score { get; set; }
}

